if (isPouringSource && sourceDrainingCount > 0 && displayTube.length > 0) {
  drainingTopPercent = Math.max(0, 100 - sourceDrainingCount * 100);
}

let risingColor: string | null = null;
let risingPercent = 0;
if (isPouringTarget && targetRisingCount > 0 && activePourColor) {
  risingColor = activePourColor;
  risingPercent = Math.min(100, targetRisingCount * 100);
}

const transformStyle: React.CSSProperties = {
  transform: isPouringSource
    ? `translate(${translateX}px, ${translateY}px) rotate(${tiltAngle}deg)`
    : isSelected
    ? 'translateY(-22px)'
    : 'translateY(0)',
  transition: isPouringSource
    ? 'transform 0.45s cubic-bezier(0.25, 1, 0.5, 1)'
    : 'transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1)',
  zIndex: isPouringSource ? 45 : isSelected ? 30 : 10,
  transformOrigin: isPouringSource ? '50% 13px' : 'center bottom',
};

interface RenderLayer {
  colorId: string;
  heightPercent: number;
  isTop: boolean;
  isBottom: boolean;
}

const layers: RenderLayer[] = [];
displayTube.forEach((colorId, idx) => {
  const isTop = idx === displayTube.length - 1 && !risingColor;
  const isBottom = idx === 0;
  const heightPct = isTop && isPouringSource ? drainingTopPercent : 100;
  if (heightPct > 0) {
    layers.push({
      colorId,
      heightPercent: heightPct,
      isTop,
      isBottom,
    });
  }
});

if (risingColor && risingPercent > 0) {
  layers.push({
    colorId: risingColor,
    heightPercent: risingPercent,
    isTop: true,
    isBottom: layers.length === 0,
  });
}

// Inner chamber coordinates (viewBox 0 0 60 190)
// Perfectly proportioned: 4 full blocks reach y=58.5, leaving ample headroom below shoulder y=38
const CHAMBER_BOTTOM_Y = 170.5;
const BLOCK_HEIGHT = 28;
const RX = 21.5;
const RY = 5.2;

let currentY = CHAMBER_BOTTOM_Y;
const calculatedLayers = layers.map((layer) => {
  const layerH = BLOCK_HEIGHT * (layer.heightPercent / 100);
  const yBottom = currentY;
  const yTop = yBottom - layerH;
  currentY = yTop;
  return { ...layer, yBottom, yTop };
});

return (
  <div
    ref={containerRef}
    className={`flex flex-col items-center group relative cursor-pointer select-none ${
      isShaking ? 'anim-invalid-shake' : ''
    }`}
    style={transformStyle}
    onClick={() => !disabled && onClick(index)}
  >
    {/* Level Completion Star Crown */}
    {isComplete && (
      <div className="absolute -top-6 left-1/2 -translate-x-1/2 z-40 bg-amber-400 text-slate-950 rounded-full w-6 h-6 flex items-center justify-center text-xs font-black shadow-lg animate-bounce border border-white">
        ★
      </div>
    )}

    {/* SVG 3D Crystal Bottle */}
    <div
      className={`relative flex flex-col items-center transition-all duration-200 ${
        isSelected
          ? 'filter drop-shadow-[0_0_16px_rgba(56,189,248,0.95)]'
          : isHintSource
          ? 'filter drop-shadow-[0_0_12px_rgba(251,191,36,0.85)]'
          : isHintTarget
          ? 'filter drop-shadow-[0_0_12px_rgba(52,211,153,0.85)]'
          : 'filter drop-shadow-[0_8px_16px_rgba(0,0,0,0.55)]'
      }`}
    >
      <svg
        viewBox="0 0 60 190"
        className="w-[52px] sm:w-[56px] h-[172px] sm:h-[184px] overflow-visible select-none"
      >
        <defs>
          {/* Deep Cosmic Sapphire Background Gradient */}
          <linearGradient id={`tube-bg-${index}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#081844" stopOpacity="0.45" />
            <stop offset="60%" stopColor="#040e2c" stopOpacity="0.65" />
            <stop offset="100%" stopColor="#020618" stopOpacity="0.85" />
          </linearGradient>

          {/* Rolled Collar Lip Gradient */}
          <linearGradient id={`lip-${index}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#93c5fd" stopOpacity="0.9" />
            <stop offset="45%" stopColor="#3b82f6" stopOpacity="0.75" />
            <stop offset="100%" stopColor="#1e3a8a" stopOpacity="0.9" />
          </linearGradient>

          {/* Left Gloss Specular Fading Gradient */}
          <linearGradient id={`specular-fade-${index}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#ffffff" stopOpacity="0.1" />
            <stop offset="6%" stopColor="#ffffff" stopOpacity="0.92" />
            <stop offset="90%" stopColor="#ffffff" stopOpacity="0.92" />
            <stop offset="100%" stopColor="#ffffff" stopOpacity="0.1" />
          </linearGradient>

          {/* 3D Lateral Cylindrical Volume Shading for each Palette Color */}
          {Object.values(COLOR_PALETTE).map((c: ColorDef) => (
            <linearGradient
              key={`grad-${c.id}-${index}`}
              id={`grad-${c.id}-${index}`}
              x1="0%"
              y1="0%"
              x2="100%"
              y2="0%"
            >
              <stop offset="0%" stopColor={c.shadeHex || c.hex} stopOpacity="1" />
              <stop offset="18%" stopColor={c.topHex || c.hex} stopOpacity="1" />
              <stop offset="55%" stopColor={c.hex} stopOpacity="1" />
              <stop offset="90%" stopColor={c.shadeHex || c.hex} stopOpacity="1" />
              <stop offset="100%" stopColor={c.shadeHex || c.hex} stopOpacity="0.95" />
            </linearGradient>
          ))}

          {/* Inner chamber clip conforming exactly to inner bottle cavity */}
          <clipPath id={`inner-clip-${index}`}>
            <path
              d="
                M 17 20
                C 17 28, 8.5 28, 8.5 38
                L 8.5 154
                C 8.5 164, 17.5 170.5, 30 170.5
                C 42.5 170.5, 51.5 164, 51.5 154
                L 51.5 38
                C 51.5 28, 43 28, 43 20
                L 43 14
                L 17 14
                Z
              "
            />
          </clipPath>
        </defs>

        {/* 1. Deep Blue Transparent Glass Back Body */}
        <path
          d="
            M 17 14
            L 17 20
            C 17 28, 6 28, 6 38
            L 6 154
            C 6 168, 16 176, 30 176
            C 44 176, 54 168, 54 154
            L 54 38
            C 54 28, 43 28, 43 20
            L 43 14
            Z
          "
          fill={`url(#tube-bg-${index})`}
        />

        {/* 2. Fluid Layers (Dynamic Pouring Stream Flow vs Stacked Gel Blocks) */}
        {isPouringSource && tiltAngle !== 0 ? (
          /* Natural Gravity Stream Flow toward mouth lip when tilted */
          <g clipPath={`url(#inner-clip-${index})`}>
            {(() => {
              if (displayTube.length === 0) return null;
              const topColorId = displayTube[displayTube.length - 1];
              const topColorDef = getColor(topColorId);
              const isTiltRight = tiltAngle > 0;

              // Find where the top pouring color run starts (consecutive blocks of same color at top)
              let runStartIdx = displayTube.length - 1;
              while (runStartIdx > 0 && displayTube[runStartIdx - 1] === topColorId) {
                runStartIdx--;
              }

              // Y-coordinate of boundary with bottom static liquid
              const yBase = CHAMBER_BOTTOM_Y - runStartIdx * BLOCK_HEIGHT;

              // How much of the top liquid is left (1 = full, 0 = drained)
              const drainPct = Math.max(0, drainingTopPercent / 100);

              // As it drains, the upper surface recedes down towards the base
              const fullHeight = (displayTube.length - runStartIdx) * BLOCK_HEIGHT;
              const curHeight = fullHeight * drainPct;
              const ySurfaceLeft = Math.max(20, yBase - curHeight);
              const ySurfaceRight = Math.max(20, yBase - curHeight);

              return (
                <>
                  {/* Non-draining layers below the pouring fluid */}
                  {displayTube.slice(0, runStartIdx).map((cId, idx) => {
                    const cDef = getColor(cId);
                    const yB = CHAMBER_BOTTOM_Y - idx * BLOCK_HEIGHT;
                    const yT = yB - BLOCK_HEIGHT;
                    return (
                      <path
                        key={`bottom-layer-${idx}`}
                        d={`M 8.5 ${yT + (isTiltRight ? 3 : -3)} L 51.5 ${yT + (isTiltRight ? -3 : 3)} L 51.5 ${yB} L 8.5 ${yB} Z`}
                        fill={`url(#grad-${cDef.id}-${index})`}
                      />
                    );
                  })}

                  {/* Unified, continuous draining fluid slide running smoothly into the neck lip */}
                  {drainPct > 0.05 && (
                    <path
                      key={`draining-wedge-${topColorId}`}
                      d={
                        isTiltRight
                          ? `
                            M 8.5 ${yBase + 3}
                            L 8.5 ${ySurfaceLeft}
                            Q 25 ${Math.max(16, ySurfaceLeft * 0.7)} 30 12
                            L 43 12
                            L 43 20
                            L 51.5 38
                            L 51.5 ${yBase - 3}
                            Z
                          `
                          : `
                            M 51.5 ${yBase + 3}
                            L 51.5 ${ySurfaceRight}
                            Q 35 ${Math.max(16, ySurfaceRight * 0.7)} 30 12
                            L 17 12
                            L 17 20
                            L 8.5 38
                            L 8.5 ${yBase - 3}
                            Z
                          `
                      }
                      fill={`url(#grad-${topColorDef.id}-${index})`}
                    />
                  )}
                </>
              );
            })()}
          </g>
        ) : (
          /* Standard Rest State: Layered 3D Cylindrical Gel Blocks */
          <g>
            {calculatedLayers.map((layer, lIdx) => {
              const cDef = getColor(layer.colorId);
              const { yBottom, yTop, isBottom, isTop } = layer;

              const bodyPath = isBottom
                ? `
                  M 8.5 ${yTop}
                  L 8.5 154
                  C 8.5 164, 17.5 170.5, 30 170.5
                  C 42.5 170.5, 51.5 164, 51.5 154
                  L 51.5 ${yTop}
                  A ${RX} ${RY} 0 0 1 8.5 ${yTop}
                  Z
                `
                : `
                  M 8.5 ${yTop}
                  L 8.5 ${yBottom}
                  A ${RX} ${RY} 0 0 0 51.5 ${yBottom}
                  L 51.5 ${yTop}
                  A ${RX} ${RY} 0 0 1 8.5 ${yTop}
                  Z
                `;

              return (
                <g key={`liquid-block-${layer.colorId}-${lIdx}`}>
                  {/* 3D Fluid Cylinder Body */}
                  <path
                    d={bodyPath}
                    fill={`url(#grad-${cDef.id}-${index})`}
                  />

                  {/* Subtle boundary crease between different stacked colors (only when different colors) */}
                  {!isBottom && calculatedLayers[lIdx - 1]?.colorId !== layer.colorId && (
                    <path
                      d={`M 8.5 ${yBottom} A ${RX} ${RY} 0 0 0 51.5 ${yBottom}`}
                      stroke="rgba(0, 0, 0, 0.28)"
                      strokeWidth="1.2"
                      fill="none"
                    />
                  )}

                  {/* Top Meniscus 3D Oval Cap */}
                  {isTop && layer.heightPercent > 4 && (
                    <g>
                      <ellipse
                        cx="30"
                        cy={yTop}
                        rx={RX}
                        ry={RY}
                        fill={cDef.topHex || cDef.hex}
                        stroke="rgba(255, 255, 255, 0.45)"
                        strokeWidth="0.8"
                      />
                      <path
                        d={`M 11.5 ${yTop + 1.8} Q 30 ${yTop + 5.5} 48.5 ${yTop + 1.8}`}
                        stroke="#ffffff"
                        strokeWidth="1.4"
                        strokeLinecap="round"
                        fill="none"
                        opacity="0.88"
                      />
                    </g>
                  )}

                  {showSymbols && (
                    <text
                      x="30"
                      y={(yTop + yBottom) / 2}
                      fill={cDef.textColor}
                      fontSize="11"
                      fontWeight="bold"
                      textAnchor="middle"
                      dominantBaseline="central"
                    >
                      {cDef.symbol}
                    </text>
                  )}
                </g>
              );
            })}
          </g>
        )}

        {/* 3. Empty Bottle Video Camera Badge */}
        {displayTube.length === 0 && !risingColor && (
          <g>
            <rect
              x="15"
              y="84"
              width="30"
              height="21"
              rx="6"
              fill="rgba(5, 18, 48, 0.65)"
              stroke="rgba(56, 189, 248, 0.75)"
              strokeWidth="1.4"
            />
            <rect x="19" y="88.5" width="13" height="12" rx="2.5" fill="#ffffff" />
            <polygon points="33,91.5 38,88 38,100.5 33,97" fill="#ffffff" />
            <polygon points="24,91.5 28.5,94.5 24,97.5" fill="#0284c7" />

            <text x="11" y="146" fill="#bae6fd" fontSize="12" className="anim-twinkle">
              ✦
            </text>
          </g>
        )}

        {/* 4. Crystal Glass Specular Reflections Layer (OVER the liquid) */}
        {/* Outer Glass Contour Outline */}
        <path
          d="
            M 17 14
            L 17 20
            C 17 28, 6 28, 6 38
            L 6 154
            C 6 168, 16 176, 30 176
            C 44 176, 54 168, 54 154
            L 54 38
            C 54 28, 43 28, 43 20
            L 43 14
          "
          fill="none"
          stroke="#38bdf8"
          strokeWidth="1.8"
          strokeLinejoin="round"
          opacity="0.82"
        />

        {/* Left Vertical High-Gloss Specular Stripe (soft fade at top & bottom) */}
        <path
          d="M 9.5 42 L 9.5 152"
          stroke="#38bdf8"
          strokeWidth="3.2"
          strokeLinecap="round"
          opacity="0.3"
        />
        <path
          d="M 9.5 42 L 9.5 152"
          stroke={`url(#specular-fade-${index})`}
          strokeWidth="1.6"
          strokeLinecap="round"
        />

        {/* Left Shoulder Curved Specular Arc */}
        <path
          d="M 10 40 C 10 29, 15 23, 19.5 18"
          stroke="#ffffff"
          strokeWidth="1.8"
          strokeLinecap="round"
          fill="none"
          opacity="0.88"
        />

        {/* Right Shoulder Curved Specular Arc */}
        <path
          d="M 40.5 18 C 45 23, 50 29, 50 40"
          stroke="#ffffff"
          strokeWidth="1.8"
          strokeLinecap="round"
          fill="none"
          opacity="0.85"
        />
        {/* Right Upper Secondary Glint Pill */}
        <ellipse
          cx="48.5"
          cy="48"
          rx="1.2"
          ry="3.5"
          fill="#ffffff"
          opacity="0.75"
        />

        {/* Solid Glass Base Refraction Smile Arcs */}
        <path
          d="M 14 171 Q 30 178 46 171"
          stroke="#93c5fd"
          strokeWidth="2.2"
          strokeLinecap="round"
          fill="none"
          opacity="0.85"
        />
        <path
          d="M 19 173 Q 30 178.5 41 173"
          stroke="#ffffff"
          strokeWidth="1.0"
          strokeLinecap="round"
          fill="none"
          opacity="0.9"
        />

        {/* 5. Top Lip Bead Collar Ring */}
        <ellipse
          cx="30"
          cy="13"
          rx="16"
          ry="4.2"
          fill={`url(#lip-${index})`}
          stroke="#38bdf8"
          strokeWidth="1.4"
        />
        {/* Rolled lip 3D depth shadow under rim */}
        <path
          d="M 14.5 13.5 C 14.5 16.5, 45.5 16.5, 45.5 13.5"
          stroke="#1e3a8a"
          strokeWidth="2"
          fill="none"
          opacity="0.7"
        />
        {/* Inner dark cavity */}
        <ellipse
          cx="30"
          cy="13"
          rx="11"
          ry="2.4"
          fill="#03081a"
          stroke="rgba(56, 189, 248, 0.45)"
          strokeWidth="0.8"
        />
        {/* Front crescent specular arc */}
        <path
          d="M 16 11.2 Q 30 9 44 11.2"
          stroke="#ffffff"
          strokeWidth="1.4"
          strokeLinecap="round"
          fill="none"
          opacity="0.92"
        />
      </svg>
    </div>

