          setTimeout(() => {
            setActiveGulpColor(null);
            if (isPuzzleComplete) {
              triggerWinCelebration(finalMoves);
            } else {
              const hasMove = hasAnyLegalMove(result.newTubes, TUBE_CAPACITY);
              if (!hasMove) {
                setIsDeadlocked(true);
              }
            }
          }, 2700);
        } else {
          // Target tube was not completed by this pour
          if (isPuzzleComplete) {
            triggerWinCelebration(finalMoves);
          } else {
            const hasMove = hasAnyLegalMove(result.newTubes, TUBE_CAPACITY);
            if (!hasMove) {
              setTimeout(() => {
                setIsDeadlocked(true);
              }, 400);
            }
          }
        }
      }

      setPourAnimation((prev) =>
        prev
